# pick_random :: [1, 2, 3]
import random

def pick_random(xs, seed=0):
    if not xs:
        return None
    rng = random.Random(seed)
    return rng.choice(xs)

if __name__ == '__main__':
    print(pick_random([1, 2, 3]))

